Use The following JSON prompt to generate the image, take into account the model's hair type @MODEL. Also then the constraints of what the prompt specifies the environment should be, se a different environment each generation. 

Also take into account the product name as below it is hard coded in, replace the hard coded name with the variable name: @PRODUCT_NAME


{
  "image_type": "before_after_comparison_marketing_visual",
  "overall_style": {
    "genre": "premium_brazilian_haircare_advertising",
    "brand_feel": "Super Bonita — carioca soul, beach lived-in luxury, effortless beauty, authentic Brazilian premium haircare",
    "visual_tone": "natural, warm, sun-kissed, authentic, editorial lifestyle photography",
    "editing_style": "very light real-world retouching only, visible natural skin texture, real hair strand variation, no plastic smoothing",
    "color_grade": "warm golden coastal daylight, subtle salt-air haze, natural skin and hair tone preservation",
    "sharpness": "natural optical sharpness, not hyper-digital",
    "noise_level": "very light natural sensor grain allowed"
  },
  "layout": {
    "format": "side_by_side_split",
    "canvas_background": "none",
    "borders": "none",
    "padding": "none",
    "panels": [
      {
        "position": "left",
        "label": "BEFORE"
      },
      {
        "position": "right",
        "label": "AFTER"
      }
    ],
    "divider": {
      "type": "none"
    },
    "realism_offset_requirement": {
      "description": "Before and After images must NOT be perfectly aligned or identical in framing",
      "reason": "Real camera captures cannot replicate exact micro positioning between shots",
      "allowed_variations": [
        "1-3 cm natural body position shift",
        "slight shoulder angle variation (1-5 degrees)",
        "minor head tilt difference",
        "subtle hair fall difference due to movement",
        "micro framing shift (very small crop or centering change)"
      ],
      "forbidden": [
        "pixel perfect duplication",
        "AI mirrored duplication",
        "identical strand placement between shots"
      ],
      "intent": "Must feel like two real photos taken seconds apart in the same shoot"
    }
  },
  "text_elements": {
    "top_labels": {
      "font_style": "clean modern sans serif",
      "font_weight": "medium",
      "letter_spacing": "slightly expanded",
      "color": "sun faded charcoal",
      "content": {
        "left": "BEFORE",
        "right": "AFTER"
      },
      "alignment": "centered above each panel"
    },
    "bottom_captions": {
      "font_style": "modern premium sans serif",
      "font_weight": "regular",
      "line_spacing": "comfortable",
      "left_panel": {
        "lines": [
          "Dull, brittle hair",
          "Weakened roots"
        ],
        "color": "warm charcoal grey"
      },
      "right_panel": {
        "lines": [
          "Shiny, strong hair",
          "Healthy, nourished roots"
        ],
        "color": "deep ocean navy (subtle, not saturated)"
      },
      "alignment": "centered under each panel"
    },
    "disclaimer": {
      "position": "very bottom center, small but readable",
      "font_style": "clean minimal sans serif",
      "font_weight": "regular",
      "font_size": "small legal style",
      "color": "soft charcoal grey",
      "content": "Results achieved using the 3 step system: Dream Curls Shampoo, Conditioner, and Hydrating Hair Mask."
    }
  },
  "subject": {
    "person_visibility": "middle back to top of head only (closer crop)",
    "gender_presentation": "feminine",
    "age_range": "young adult",
    "skin_tone": "light to tan sun-exposed natural Brazilian coastal tone",
    "pose": {
      "camera_facing": "back facing camera",
      "posture": "relaxed natural standing posture",
      "head_position": "natural slight organic micro tilt"
    },
    "clothing": {
      "top": {
        "style_inspiration": "trendy among young Brazilian coastal crowd",
        "type_options": [
          "ribbed fitted crop tee (modest length, not revealing)",
          "minimalist tank with thicker straps",
          "fitted baby tee"
        ],
        "color_palette": [
          "sand",
          "sun faded white",
          "muted terracotta",
          "soft sage",
          "warm beige"
        ],
        "fit": "modern fitted but casual",
        "texture": "real cotton or rib knit visible fiber texture"
      }
    }
  },
  "hair_before": {
    "color": "medium warm brown or deep sun warmed brown",
    "length": "mid back length",
    "density": "medium natural density",
    "texture": "natural loose beach wave (2A–2B range)",
    "condition": [
      "slightly dull finish",
      "minor dryness on mids and ends",
      "subtle frizz halo in humidity",
      "irregular natural wave pattern",
      "some flyaways catching backlight"
    ],
    "shape": "natural beach wave with slightly stretched ends",
    "root_appearance": "natural, slightly flat from humidity and daily wear"
  },
  "hair_after": {
    "color": "same base color, slightly richer and healthier looking (not dyed, not darker artificially)",
